import sys, json

def trunc(s, n=300):
    if s is None: return ""
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def get_text_from_content(content):
    out = []
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                out.append(str(c))
                continue
            t = c.get("type")
            if t == "text":
                out.append(c.get("text",""))
            elif t == "tool_use":
                out.append(f"[TOOL_USE {c.get('name')}] input={trunc(json.dumps(c.get('input',{})), 400)}")
            elif t == "tool_result":
                cont = c.get("content")
                if isinstance(cont, list):
                    inner = " ".join(get_text_from_content(cont))
                else:
                    inner = str(cont)
                out.append(f"[TOOL_RESULT err={c.get('is_error')}] {trunc(inner,300)}")
            else:
                out.append(f"[{t}] {trunc(json.dumps(c), 200)}")
    return "\n".join(out) if isinstance(out, list) else out

for line in sys.stdin:
    line = line.strip()
    if not line: continue
    try:
        d = json.loads(line)
    except Exception as e:
        print("PARSEERR", e)
        continue
    typ = d.get("type")
    ts = d.get("timestamp","")
    if typ == "queue-operation":
        print(f"[{ts}] QUEUE({d.get('operation')}): {trunc(d.get('content'), 500)}")
        continue
    if typ == "ai-title":
        print(f"TITLE: {d.get('aiTitle')}")
        continue
    msg = d.get("message")
    if msg:
        role = msg.get("role")
        content = msg.get("content")
        text = get_text_from_content(content)
        # skip huge hook_success dumps at start
        print(f"[{ts}] {role}: {trunc(text, 600)}")
        continue
    attachment = d.get("attachment")
    if attachment:
        print(f"[{ts}] ATTACH({attachment.get('type')}/{attachment.get('hookName') or attachment.get('hookEvent')}): {trunc(attachment.get('content'), 200)}")
        continue
    print(f"[{ts}] OTHER type={typ}: {trunc(json.dumps(d), 200)}")

