import json, sys

def condense(path, out):
    with open(path) as f, open(out, 'w') as o:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception as e:
                o.write(f"LINE {i} PARSE ERROR {e}\n")
                continue
            ts = obj.get('timestamp') or obj.get('ts') or ''
            typ = obj.get('type', '')
            role = obj.get('role', '')
            summary = ''
            msg = obj.get('message')
            content = None
            if isinstance(msg, dict):
                content = msg.get('content')
                role = msg.get('role', role)
            elif 'content' in obj:
                content = obj.get('content')

            pieces = []
            if isinstance(content, str):
                pieces.append(content[:300])
            elif isinstance(content, list):
                for c in content:
                    if not isinstance(c, dict):
                        continue
                    ctype = c.get('type')
                    if ctype == 'text':
                        pieces.append('[text] ' + c.get('text','')[:300])
                    elif ctype == 'tool_use':
                        inp = json.dumps(c.get('input', {}))[:300]
                        pieces.append(f"[tool_use:{c.get('name')}] {inp}")
                    elif ctype == 'tool_result':
                        cont = c.get('content')
                        if isinstance(cont, list):
                            txt = ' '.join(x.get('text','')[:200] for x in cont if isinstance(x, dict))
                        else:
                            txt = str(cont)[:200]
                        pieces.append(f"[tool_result] {txt[:300]}")
                    else:
                        pieces.append(f"[{ctype}] " + json.dumps(c)[:200])
            summary = ' | '.join(pieces)
            usage = obj.get('usage') or (msg.get('usage') if isinstance(msg, dict) else None)
            usage_s = json.dumps(usage) if usage else ''
            o.write(f"L{i}\tts={ts}\ttype={typ}\trole={role}\t{summary}\t{usage_s}\n")

condense(sys.argv[1], sys.argv[2])

